/**
 * A writer for WebM fixtures, generated by code: Opus (silent 20 ms CELT
 * packets, which decoders accept) or Vorbis (placeholder packets, for the
 * probe only), with the shapes `MediaRecorder` and muxers write: unknown-size
 * Segments and Clusters, no Duration, the three lacings, and a video track.
 */

const text = (s: string) => [...s].map((c) => c.charCodeAt(0));
const u16le = (v: number) => [v & 0xff, (v >> 8) & 0xff];
const u32le = (v: number) => [v & 0xff, (v >>> 8) & 0xff, (v >>> 16) & 0xff, (v >>> 24) & 0xff];

function idBytes(id: number): number[] {
  const out: number[] = [];
  for (let v = id; v > 0; v = Math.floor(v / 256)) out.unshift(v % 256);
  return out;
}

/** A size as an EBML variable-length integer, or the 8-byte "unknown" value. */
export function sizeBytes(size: number | "unknown"): number[] {
  if (size === "unknown") return [0x01, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff];
  if (size < 0x7f) return [0x80 | size];
  if (size < 0x3fff) return [0x40 | (size >> 8), size & 0xff];
  if (size < 0x1fffff) return [0x20 | (size >> 16), (size >> 8) & 0xff, size & 0xff];
  return [0x10 | ((size >>> 24) & 0x0f), (size >>> 16) & 0xff, (size >>> 8) & 0xff, size & 0xff];
}

function element(id: number, ...data: number[][]): number[] {
  const body = data.flat();
  return [...idBytes(id), ...sizeBytes(body.length), ...body];
}
const unsized = (id: number, ...data: number[][]) => [
  ...idBytes(id),
  ...sizeBytes("unknown"),
  ...data.flat(),
];
const uint = (id: number, value: number) => {
  const bytes: number[] = [];
  for (let v = value; v > 0 || bytes.length === 0; v = Math.floor(v / 256)) bytes.unshift(v % 256);
  return element(id, bytes);
};
const float64 = (id: number, value: number) => {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, value);
  return element(id, [...new Uint8Array(view.buffer)]);
};
const string = (id: number, value: string) => element(id, text(value));

export type Lacing = "none" | "xiph" | "ebml" | "fixed";

/** A SimpleBlock of `frames` on `track`, with the given lacing. */
export function simpleBlock(
  track: number,
  timecode: number,
  frames: number[][],
  lacing: Lacing,
): number[] {
  const flags = 0x80 | ({ none: 0, xiph: 1, fixed: 2, ebml: 3 }[lacing] << 1);
  const head = [0x80 | track, (timecode >> 8) & 0xff, timecode & 0xff, flags];
  if (lacing !== "none") {
    head.push(frames.length - 1);
    if (lacing === "xiph") {
      for (const frame of frames.slice(0, -1)) {
        let size = frame.length;
        while (size >= 255) {
          head.push(255);
          size -= 255;
        }
        head.push(size);
      }
    } else if (lacing === "ebml") {
      head.push(...sizeBytes((frames[0] as number[]).length));
      for (let i = 1; i < frames.length - 1; i += 1) {
        const delta = (frames[i] as number[]).length - (frames[i - 1] as number[]).length;
        head.push(0x80 | (delta + 63)); // one-byte signed difference, bias 63
      }
    }
  }
  return element(0xa3, head, ...frames);
}

export interface WebmOptions {
  readonly codec?: "opus" | "vorbis" | "aac";
  /** For AAC, leave out the CodecPrivate (the AudioSpecificConfig). */
  readonly withoutCodecPrivate?: boolean;
  readonly packets: number;
  readonly framesPerBlock?: number;
  readonly blocksPerCluster?: number;
  readonly lacing?: Lacing;
  /** Unknown-size Segment and Clusters, as MediaRecorder writes. */
  readonly unknownSizes?: boolean;
  /** The Duration in milliseconds, which MediaRecorder leaves out. */
  readonly durationMs?: number;
  /** A video track, with blocks of its own between the audio's. */
  readonly videoTrack?: boolean;
  readonly secondAudioTrack?: boolean;
  /** Packets to use instead of the silent ones. */
  readonly customPackets?: readonly number[][];
}

const SILENT_OPUS = [0xfc, 0xff, 0xfe];

/** AAC-LC at 24 kHz, stereo: object type 2, rate index 6, configuration 2. */
const AAC_CONFIG = [0x13, 0x10];
const SILENT_AAC = [0x21, 0x00, 0x49, 0x90, 0x02, 0x19, 0x00, 0x23, 0x80];

function audioTrack(
  number: number,
  codec: "opus" | "vorbis" | "aac",
  withoutPrivate = false,
): number[] {
  const opusHead = [...text("OpusHead"), 1, 2, ...u16le(312), ...u32le(48_000), ...u16le(0), 0];
  const vorbisId = [
    0x01,
    ...text("vorbis"),
    ...u32le(0),
    2,
    ...u32le(44_100),
    ...u32le(0),
    ...u32le(128_000),
    ...u32le(0),
    0xb8,
    0x01,
  ];
  const vorbisComment = [0x03, ...text("vorbis"), ...u32le(0), ...u32le(0), 0x01];
  const vorbisSetup = [0x05, ...text("vorbis"), ...new Array(20).fill(0x2a)];
  const priv =
    codec === "opus"
      ? opusHead
      : codec === "aac"
        ? AAC_CONFIG
        : [2, vorbisId.length, vorbisComment.length, ...vorbisId, ...vorbisComment, ...vorbisSetup];
  const codecId = { opus: "A_OPUS", vorbis: "A_VORBIS", aac: "A_AAC" }[codec];
  const rate = { opus: 48_000, vorbis: 44_100, aac: 48_000 }[codec];
  return element(
    0xae,
    uint(0xd7, number),
    uint(0x73c5, number),
    uint(0x83, 2),
    string(0x86, codecId),
    ...(withoutPrivate ? [] : [element(0x63a2, priv)]),
    element(0xe1, float64(0xb5, rate), uint(0x9f, 2)),
  );
}

export function webmFile(options: WebmOptions): Uint8Array<ArrayBuffer> {
  const codec = options.codec ?? "opus";
  const lacing = options.lacing ?? "none";
  const perBlock = lacing === "none" ? 1 : (options.framesPerBlock ?? 4);
  const perCluster = options.blocksPerCluster ?? 10;
  const packets =
    options.customPackets ??
    Array.from({ length: options.packets }, () =>
      codec === "opus"
        ? SILENT_OPUS
        : codec === "aac"
          ? SILENT_AAC
          : [0x00, ...new Array(20).fill(0x11)],
    );

  const header = element(
    0x1a45dfa3,
    uint(0x4286, 1),
    uint(0x42f7, 1),
    uint(0x42f2, 4),
    uint(0x42f3, 8),
    string(0x4282, "webm"),
    uint(0x4287, 4),
    uint(0x4285, 2),
  );
  const info = element(
    0x1549a966,
    uint(0x2ad7b1, 1_000_000),
    string(0x4d80, "fixtures"),
    string(0x5741, "fixtures"),
    ...(options.durationMs === undefined ? [] : [float64(0x4489, options.durationMs)]),
  );
  const entries = [audioTrack(1, codec, options.withoutCodecPrivate)];
  if (options.secondAudioTrack) entries.push(audioTrack(3, codec));
  if (options.videoTrack) {
    entries.push(
      element(
        0xae,
        uint(0xd7, 2),
        uint(0x73c5, 2),
        uint(0x83, 1),
        string(0x86, "V_VP8"),
        element(0xe0, uint(0xb0, 16), uint(0xba, 16)),
      ),
    );
  }
  const tracks = element(0x1654ae6b, ...entries);

  const blocks: number[][] = [];
  for (let start = 0; start < packets.length; start += perBlock) {
    blocks.push(
      simpleBlock(
        1,
        blocks.length * 20 * perBlock,
        packets.slice(start, start + perBlock) as number[][],
        lacing,
      ),
    );
    if (options.videoTrack)
      blocks.push(simpleBlock(2, blocks.length * 20, [[0x9d, 0x01, 0x2a, 0, 0, 0]], "none"));
  }
  const clusters: number[] = [];
  for (let start = 0; start < blocks.length; start += perCluster) {
    const content = [uint(0xe7, start * 20), ...blocks.slice(start, start + perCluster)];
    clusters.push(
      ...(options.unknownSizes ? unsized(0x1f43b675, ...content) : element(0x1f43b675, ...content)),
    );
  }
  const segment = options.unknownSizes
    ? unsized(0x18538067, info, tracks, clusters)
    : element(0x18538067, info, tracks, clusters);
  return Uint8Array.from([...header, ...segment]);
}
